/* The bench's cases, generated by scripts/device_cases.py from the host CLI's answers. */
#ifndef CASES_H
#define CASES_H

typedef struct {
    const char *name;
    const char *expr;
    int var, angle;
    int simplify;           /* 1: casim_simplify; 0: casim_derive */
    int chars;              /* the equation's length in characters */
    int status;             /* the host's status (0 OK, 3 TOO_LONG, ...) */
    const char *want;       /* the host's text ("" unless OK) */
} bench_case;

extern const bench_case cases[];
extern const int case_count;

#endif
